/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input wire [7:0] in,
    output reg [2:0] pos
);
    always @(*) begin
        casez (in)
            8'b???????1: pos = 3'd0;
            8'b??????10: pos = 3'd1;
            8'b?????100: pos = 3'd2;
            8'b????1000: pos = 3'd3;
            8'b???10000: pos = 3'd4;
            8'b??100000: pos = 3'd5;
            8'b?1000000: pos = 3'd6;
            8'b10000000: pos = 3'd7;
            default: pos = 3'd0;
        endcase
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    reg [7:0] in;
    wire [2:0] pos;
    integer vector;
    integer checks = 0;
    TopModule dut (.in(in), .pos(pos));

    task check_vector(input reg [7:0] value);
        integer bit_index;
        reg [2:0] expected;
        begin
            expected = 3'"'d0;
            // Independent oracle: later updates select the smaller set index.
            for (bit_index = 7; bit_index >= 0; bit_index = bit_index - 1)
                if (value[bit_index]) expected = bit_index;
            in = value;
            #1;
            if (pos "'!== expected)
                $fatal(1, "in=%b expected=%0d observed=%0d", value, expected, pos);
            checks = checks + 1;
        end
    endtask

    initial begin
        check_vector(8'"'b10010000);
        check_vector(8'b00000000);
        check_vector(8'b11111111);
        for (vector = 0; vector < 256; vector = vector + 1)
            check_vector(vector[7:0]);
        for (vector = 255; vector >= 0; vector = vector - 1)
            check_vector(vector[7:0]);
        "'$display("PASS: %0d priority encoder checks", checks);
        $finish;
    end

    initial begin
        #1000;
        $fatal(1, "Development test timeout");
    end
endmodule
EOF
python3 dev_check.py --label initial'

